import csv, sys, os
os.chdir(sys.argv[1])
def r(f):
    return dict((x['region'], x) for x in csv.DictReader(open(f)))
a, b = r('last_week.csv'), r('this_week.csv')
for m in ['orders', 'revenue_gbp', 'active_customers']:
    ta = tb = 0
    for k in a:
        x, y = int(a[k][m]), int(b[k][m])
        ta += x
        tb += y
        print(m, k, x, y, y - x, "%.1f%%" % ((y - x) / x * 100))
    print(m, 'TOTAL', ta, tb, tb - ta, "%.1f%%" % ((tb - ta) / ta * 100))
for k in a:
    print(k, 'AOV', round(int(a[k]['revenue_gbp']) / int(a[k]['orders']), 2), round(int(b[k]['revenue_gbp']) / int(b[k]['orders']), 2))

